// Поле todo — что осталось после пакета правок beta 2026-11-13 (умолчания, описания, min / max, порядок осей сделаны в Figma).

const PLASHKA = 'Плашка: слой `state/layer` × `state/hover` 6 % / `state/pressed` 10 %; Disabled — токены `*/disabled`';
const SELECT = 'Контрол выбора: слой `state/layer` на глифе, выбранное — `control/checked`';
