const NONE = 'нет: неинтерактивный элемент';
const ZONES = 'Зона нажатия ≥ `touch/min`: Web 24, касание 44 (слои `hit area · web` / `hit area · app`, проверка — Show hit area); безопасное поле — `control/safe-margin`.';
const FOCUS = 'Кольцо фокуса — только при навигации с клавиатуры, появляется сразу, без анимации (`service-layers.md`).';
const MOTION = 'Hover: слой 0 → 6 %, `motion/duration/feedback` (120 мс), `motion/easing/standard`. «Уменьшить движение»: длительности ≈ 0.';
