const LONG = (n) => `Длинный текст: одна строка, усечение многоточием по max-width ${n}; полный текст — в \`title\` / тултипе.`;
const OK = '0 замечаний';
const INPUT_ADDON = { identity: ['Страница «Input» (уровень молекулы), сам элемент — атом слота поля. Отдельно от поля не используется.'], platformsList: 'Web, Mobile web, iOS, Android (вместе с Input)', group: 'наследует состояние поля: Disabled / Read-only поля гасит аддон' };

